use vstd::prelude::*;

verus! {

fn copy(arr: &Vec<i8>) -> (result: Vec<i8>)
    ensures
        result.len() == arr.len(),
        forall|i: int|
            0 <= i < arr.len() ==> result[i] == arr[i],
{
    let mut result: Vec<i8> = Vec::new();
    let mut idx: usize = 0;

    while idx < arr.len()
        invariant
            result.len() == idx,
            idx <= arr.len(),
            forall|i: int| 0 <= i < idx ==> result[i] == arr[i],
    {
        result.push(arr[idx]);
        idx += 1;
    }

    result
}

} // verus!